CREATE OR REPLACE FUNCTION public.apply_inventory_on_order_fulfilled()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  r RECORD;
BEGIN
  IF NEW.fulfillment_status = 'fulfilled'::fulfillment_status
     AND OLD.fulfillment_status IS DISTINCT FROM 'fulfilled'::fulfillment_status THEN
    FOR r IN
      SELECT variant_id, quantity
      FROM public.order_items
      WHERE order_id = NEW.id
    LOOP
      UPDATE public.inventory
      SET
        reserved_quantity = GREATEST(0, reserved_quantity - r.quantity),
        updated_at = now()
      WHERE variant_id = r.variant_id;
    END LOOP;
  END IF;

  RETURN NEW;
END;
$function$;
--> statement-breakpoint
COMMENT ON FUNCTION apply_inventory_on_order_fulfilled() IS 'On fulfillment, releases the reservation only. inventory.quantity was already
   decremented by the application at order-creation time.';
--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.cancel_order(p_order_id uuid, p_reason text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_result JSONB;
  v_order_status order_status;
  v_order_item RECORD;
  v_movement_id UUID;
  v_restored_items JSONB[] := '{}';
  v_total_restored INTEGER := 0;
BEGIN
  -- Get current order status
  SELECT status INTO v_order_status
  FROM orders
  WHERE id = p_order_id;

  -- Check if order can be cancelled
  IF v_order_status IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Order not found'
    );
  END IF;

  IF v_order_status IN ('cancelled', 'delivered', 'refunded') THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Order cannot be cancelled in current status: ' || v_order_status
    );
  END IF;

  -- Update order status
  UPDATE orders
  SET
    status = 'cancelled',
    internal_notes = COALESCE(internal_notes, '') ||
      CASE WHEN internal_notes IS NOT NULL THEN '; ' ELSE '' END ||
      'Cancelled on ' || NOW()::TEXT ||
      CASE WHEN p_reason IS NOT NULL THEN ': ' || p_reason ELSE '' END,
    updated_at = NOW()
  WHERE id = p_order_id;

  -- Restore stock for each order item
  FOR v_order_item IN
    SELECT oi.id, oi.variant_id, oi.quantity, oi.product_name, oi.variant_name
    FROM order_items oi
    WHERE oi.order_id = p_order_id
  LOOP
    -- Restore stock
    UPDATE inventory
    SET quantity = quantity + v_order_item.quantity
    WHERE variant_id = v_order_item.variant_id;

    -- Log movement
    v_movement_id := log_inventory_movement(
      v_order_item.variant_id,
      'cancel',
      'order_cancelled',
      v_order_item.quantity,
      p_order_id,
      v_order_item.id,
      p_user_id,
      NULL, -- reference_number
      'Stock restored due to order cancellation',
      NULL, -- cost_per_unit
      'main'
    );

    -- Add to restored items
    v_restored_items := array_append(v_restored_items, jsonb_build_object(
      'order_item_id', v_order_item.id,
      'variant_id', v_order_item.variant_id,
      'product_name', v_order_item.product_name,
      'variant_name', v_order_item.variant_name,
      'quantity_restored', v_order_item.quantity,
      'movement_id', v_movement_id
    ));

    v_total_restored := v_total_restored + v_order_item.quantity;
  END LOOP;

  v_result := jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'total_items_restored', array_length(v_restored_items, 1),
    'total_quantity_restored', v_total_restored,
    'restored_items', to_jsonb(v_restored_items),
    'message', 'Order cancelled and stock restored successfully'
  );

  RETURN v_result;
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', SQLERRM,
      'message', 'Failed to cancel order'
    );
END;
$function$;
--> statement-breakpoint
COMMENT ON FUNCTION cancel_order(p_order_id uuid, p_reason text, p_user_id uuid) IS 'Cancels an order and restores stock to inventory';
--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.check_low_stock()
 RETURNS TABLE(product_id uuid, product_name text, variant_id uuid, variant_name text, current_stock integer, low_stock_threshold integer, reorder_point integer, reorder_quantity integer)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    p.id as product_id,
    p.name as product_name,
    pv.id as variant_id,
    pv.name as variant_name,
    i.quantity as current_stock,
    p.low_stock_threshold,
    i.reorder_point,
    i.reorder_quantity
  FROM products p
  JOIN product_variants pv ON p.id = pv.product_id
  JOIN inventory i ON pv.id = i.variant_id
  WHERE p.is_active = true
    AND pv.is_active = true
    AND i.quantity <= COALESCE(p.low_stock_threshold, 10)
  ORDER BY i.quantity ASC;
END;
$function$;
--> statement-breakpoint
COMMENT ON FUNCTION check_low_stock() IS 'Tested and working - returns products below low stock threshold';
