CREATE OR REPLACE FUNCTION public.decrease_stock(p_variant_id uuid, p_quantity integer, p_order_id uuid DEFAULT NULL::uuid, p_order_item_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT NULL::uuid, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_location text DEFAULT 'main'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_movement_id UUID;
  v_current_quantity INTEGER;
  v_new_quantity INTEGER;
BEGIN
  IF p_quantity <= 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Quantity must be greater than 0'
    );
  END IF;

  SELECT COALESCE(quantity, 0) INTO v_current_quantity
  FROM inventory
  WHERE variant_id = p_variant_id AND location = p_location;

  IF v_current_quantity < p_quantity THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Insufficient stock. Available: ' || v_current_quantity || ', Required: ' || p_quantity
    );
  END IF;

  v_new_quantity := v_current_quantity - p_quantity;

  UPDATE inventory
  SET
    quantity = quantity - p_quantity,
    updated_at = NOW()
  WHERE variant_id = p_variant_id AND location = p_location;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Inventory record not found for variant: ' || p_variant_id
    );
  END IF;

  v_movement_id := log_inventory_movement(
    p_variant_id,
    'sale',
    'customer_order',
    -p_quantity,
    p_order_id,
    p_order_item_id,
    p_user_id,
    p_reference_number,
    p_notes,
    NULL,
    p_location
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Stock decreased successfully',
    'data', jsonb_build_object(
      'variant_id', p_variant_id,
      'location', p_location,
      'quantity_decreased', p_quantity,
      'previous_quantity', v_current_quantity,
      'new_quantity', v_new_quantity,
      'movement_id', v_movement_id
    )
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Failed to decrease stock: ' || SQLERRM
    );
END;
$function$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.get_guest_order(p_order_id uuid, p_guest_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  result jsonb;
BEGIN
  IF p_order_id IS NULL OR p_guest_token IS NULL OR length(trim(p_guest_token)) = 0 THEN
    RETURN NULL;
  END IF;

  SELECT
    jsonb_build_object(
      'id', o.id,
      'order_number', o.order_number,
      'status', o.status,
      'payment_status', o.payment_status,
      'fulfillment_status', o.fulfillment_status,
      'subtotal', o.subtotal,
      'tax_amount', o.tax_amount,
      'shipping_amount', o.shipping_amount,
      'discount_amount', o.discount_amount,
      'total_amount', o.total_amount,
      'created_at', o.created_at,
      'order_items',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', oi.id,
              'product_id', oi.product_id,
              'variant_id', oi.variant_id,
              'product_name', oi.product_name,
              'variant_name', oi.variant_name,
              'sku', oi.sku,
              'quantity', oi.quantity,
              'unit_price', oi.unit_price,
              'total_price', oi.total_price,
              'product',
              (
                SELECT jsonb_build_object(
                  'id', p.id,
                  'name', p.name,
                  'slug', p.slug,
                  'images',
                  COALESCE(
                    (
                      SELECT jsonb_agg(
                        jsonb_build_object(
                          'id', pi.id,
                          'url', pi.url,
                          'alt_text', pi.alt_text,
                          'is_primary', pi.is_primary,
                          'sort_order', pi.sort_order
                        )
                        ORDER BY pi.is_primary DESC NULLS LAST, pi.sort_order NULLS LAST
                      )
                      FROM public.product_images pi
                      WHERE pi.product_id = p.id
                    ),
                    '[]'::jsonb
                  )
                )
                FROM public.products p
                WHERE p.id = oi.product_id
              ),
              'variant',
              (
                SELECT jsonb_build_object(
                  'id', pv.id,
                  'name', pv.name,
                  'size', pv.size,
                  'color', pv.color
                )
                FROM public.product_variants pv
                WHERE pv.id = oi.variant_id
              )
            )
            ORDER BY oi.created_at
          )
          FROM public.order_items oi
          WHERE oi.order_id = o.id
        ),
        '[]'::jsonb
      )
    )
  INTO result
  FROM public.orders o
  WHERE o.id = p_order_id
    AND o.guest_token = p_guest_token
    AND (o.guest_token_expires IS NULL OR o.guest_token_expires > now());

  RETURN result;
END;
$function$;
