CREATE OR REPLACE FUNCTION public.get_inventory_summary(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_result JSONB;
  v_variant_summary JSONB[] := '{}';
  v_variant RECORD;
  v_total_stock INTEGER := 0;
  v_total_reserved INTEGER := 0;
  v_total_available INTEGER := 0;
  v_low_stock_variants INTEGER := 0;
BEGIN
  -- Get variant summaries
  FOR v_variant IN
    SELECT
      pv.id as variant_id,
      pv.name as variant_name,
      pv.sku,
      pv.size,
      pv.color,
      COALESCE(i.quantity, 0) as stock_quantity,
      COALESCE(i.reserved_quantity, 0) as reserved_quantity,
      COALESCE(i.available_quantity, 0) as available_quantity,
      COALESCE(i.reorder_point, 0) as reorder_point,
      COALESCE(i.reorder_quantity, 0) as reorder_quantity,
      p.low_stock_threshold,
      CASE WHEN COALESCE(i.quantity, 0) <= COALESCE(p.low_stock_threshold, 10) THEN true ELSE false END as is_low_stock
    FROM product_variants pv
    LEFT JOIN inventory i ON pv.id = i.variant_id
    JOIN products p ON pv.product_id = p.id
    WHERE pv.product_id = p_product_id
    ORDER BY pv.sort_order, pv.name
  LOOP
    v_variant_summary := array_append(v_variant_summary, to_jsonb(v_variant));

    v_total_stock := v_total_stock + v_variant.stock_quantity;
    v_total_reserved := v_total_reserved + v_variant.reserved_quantity;
    v_total_available := v_total_available + v_variant.available_quantity;

    IF v_variant.is_low_stock THEN
      v_low_stock_variants := v_low_stock_variants + 1;
    END IF;
  END LOOP;

  v_result := jsonb_build_object(
    'product_id', p_product_id,
    'total_stock', v_total_stock,
    'total_reserved', v_total_reserved,
    'total_available', v_total_available,
    'low_stock_variants', v_low_stock_variants,
    'total_variants', array_length(v_variant_summary, 1),
    'variants', to_jsonb(v_variant_summary)
  );

  RETURN v_result;
END;
$function$;
--> statement-breakpoint
COMMENT ON FUNCTION get_inventory_summary(p_product_id uuid) IS 'Returns comprehensive inventory summary for a product';
--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.log_inventory_movement(p_variant_id uuid, p_movement_type movement_type, p_reason movement_reason, p_quantity integer, p_order_id uuid DEFAULT NULL::uuid, p_order_item_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT NULL::uuid, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_cost_per_unit numeric DEFAULT NULL::numeric, p_location text DEFAULT 'main'::text)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_movement_id UUID;
  v_previous_quantity INTEGER;
  v_new_quantity INTEGER;
  v_on_hand INTEGER;
  v_total_cost DECIMAL(10,2);
BEGIN
  v_on_hand := COALESCE(
    (
      SELECT quantity
      FROM inventory
      WHERE variant_id = p_variant_id AND location = p_location
      LIMIT 1
    ),
    0
  );

  IF p_movement_type IN ('reserve', 'unreserve')
     OR (p_movement_type = 'sale' AND p_reason = 'customer_order') THEN
    v_previous_quantity := v_on_hand;
    v_new_quantity := v_on_hand;
  ELSE
    v_new_quantity := v_on_hand;
    v_previous_quantity := v_on_hand - p_quantity;
  END IF;

  v_total_cost := p_quantity * COALESCE(p_cost_per_unit, 0);

  INSERT INTO inventory_movements (
    variant_id,
    movement_type,
    reason,
    quantity,
    previous_quantity,
    new_quantity,
    order_id,
    order_item_id,
    user_id,
    reference_number,
    notes,
    cost_per_unit,
    total_cost,
    location
  ) VALUES (
    p_variant_id,
    p_movement_type,
    p_reason,
    p_quantity,
    v_previous_quantity,
    v_new_quantity,
    p_order_id,
    p_order_item_id,
    p_user_id,
    p_reference_number,
    p_notes,
    p_cost_per_unit,
    v_total_cost,
    p_location
  ) RETURNING id INTO v_movement_id;

  RETURN v_movement_id;
END;
$function$;
--> statement-breakpoint
COMMENT ON FUNCTION log_inventory_movement(p_variant_id uuid, p_movement_type movement_type, p_reason movement_reason, p_quantity integer, p_order_id uuid, p_order_item_id uuid, p_user_id uuid, p_reference_number text, p_notes text, p_cost_per_unit numeric, p_location text) IS 'Logs inventory movements. previous_quantity/new_quantity reflect on-hand quantity; for reserve/unreserve and sale+customer_order (reserved-only change), both match current on-hand.';
--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.process_order_completion(p_order_id uuid, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_result JSONB;
  v_order_item RECORD;
  v_movement_id UUID;
  v_processed_items JSONB[] := '{}';
  v_total_processed INTEGER := 0;
BEGIN
  -- Get order status
  IF NOT EXISTS (SELECT 1 FROM orders WHERE id = p_order_id) THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Order not found'
    );
  END IF;

  -- Process each order item
  FOR v_order_item IN
    SELECT oi.id, oi.variant_id, oi.quantity, oi.product_name, oi.variant_name
    FROM order_items oi
    WHERE oi.order_id = p_order_id
  LOOP
    -- Convert reserved stock to sold (decrease reserved quantity)
    UPDATE inventory
    SET reserved_quantity = reserved_quantity - v_order_item.quantity
    WHERE variant_id = v_order_item.variant_id;

    -- Log movement
    v_movement_id := log_inventory_movement(
      v_order_item.variant_id,
      'sale',
      'customer_order',
      -v_order_item.quantity, -- Negative for decrease
      p_order_id,
      v_order_item.id,
      p_user_id,
      NULL, -- reference_number
      'Stock sold - order completed',
      NULL, -- cost_per_unit
      'main'
    );

    -- Add to processed items
    v_processed_items := array_append(v_processed_items, jsonb_build_object(
      'order_item_id', v_order_item.id,
      'variant_id', v_order_item.variant_id,
      'product_name', v_order_item.product_name,
      'variant_name', v_order_item.variant_name,
      'quantity_sold', v_order_item.quantity,
      'movement_id', v_movement_id
    ));

    v_total_processed := v_total_processed + v_order_item.quantity;
  END LOOP;

  v_result := jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'total_items_processed', array_length(v_processed_items, 1),
    'total_quantity_sold', v_total_processed,
    'processed_items', to_jsonb(v_processed_items),
    'message', 'Order completion processed successfully'
  );

  RETURN v_result;
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', SQLERRM,
      'message', 'Failed to process order completion'
    );
END;
$function$;
--> statement-breakpoint
COMMENT ON FUNCTION process_order_completion(p_order_id uuid, p_user_id uuid) IS 'Converts reserved stock to sold stock';
--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.product_images_enforce_single_primary()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.is_primary IS TRUE THEN
    UPDATE public.product_images
    SET is_primary = FALSE
    WHERE product_id = NEW.product_id
      AND is_primary = TRUE
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);
  END IF;
  RETURN NEW;
END;
$function$;
