CREATE OR REPLACE FUNCTION public.reserve_stock(p_variant_id uuid, p_quantity integer, p_order_id uuid DEFAULT NULL::uuid, p_order_item_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT NULL::uuid, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_location text DEFAULT 'main'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_movement_id UUID;
  v_current_quantity INTEGER;
  v_current_reserved INTEGER;
  v_new_reserved INTEGER;
BEGIN
  IF p_quantity <= 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Quantity must be greater than 0'
    );
  END IF;

  SELECT
    COALESCE(quantity, 0),
    COALESCE(reserved_quantity, 0)
  INTO v_current_quantity, v_current_reserved
  FROM inventory
  WHERE variant_id = p_variant_id AND location = p_location;

  IF (v_current_quantity - v_current_reserved) < p_quantity THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Insufficient available stock. Available: ' || (v_current_quantity - v_current_reserved) || ', Required: ' || p_quantity
    );
  END IF;

  v_new_reserved := v_current_reserved + p_quantity;

  UPDATE inventory
  SET
    reserved_quantity = reserved_quantity + p_quantity,
    updated_at = NOW()
  WHERE variant_id = p_variant_id AND location = p_location;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Inventory record not found for variant: ' || p_variant_id
    );
  END IF;

  v_movement_id := log_inventory_movement(
    p_variant_id,
    'reserve',
    'checkout_reserve',
    p_quantity,
    p_order_id,
    p_order_item_id,
    p_user_id,
    p_reference_number,
    p_notes,
    NULL,
    p_location
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Stock reserved successfully',
    'data', jsonb_build_object(
      'variant_id', p_variant_id,
      'location', p_location,
      'quantity_reserved', p_quantity,
      'previous_reserved', v_current_reserved,
      'new_reserved', v_new_reserved,
      'available_quantity', v_current_quantity - v_new_reserved,
      'movement_id', v_movement_id
    )
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Failed to reserve stock: ' || SQLERRM
    );
END;
$function$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.restock_inventory(p_variant_id uuid, p_quantity integer, p_cost_per_unit numeric DEFAULT NULL::numeric, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_location text DEFAULT 'main'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_result JSONB;
  v_movement_id UUID;
  v_current_quantity INTEGER;
  v_new_quantity INTEGER;
BEGIN
  -- Validate quantity
  IF p_quantity <= 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Quantity must be greater than 0'
    );
  END IF;

  -- Get current quantity
  SELECT COALESCE(quantity, 0) INTO v_current_quantity
  FROM inventory
  WHERE variant_id = p_variant_id AND location = p_location;

  -- Calculate new quantity
  v_new_quantity := v_current_quantity + p_quantity;

  -- Update inventory using UPSERT
  INSERT INTO inventory (variant_id, quantity, location)
  VALUES (p_variant_id, p_quantity, p_location)
  ON CONFLICT (variant_id, location)
  DO UPDATE SET
    quantity = inventory.quantity + p_quantity,
    updated_at = NOW();

  -- Log movement
  v_movement_id := log_inventory_movement(
    p_variant_id,
    'restock',
    'purchase_order',
    p_quantity,
    NULL, -- order_id
    NULL, -- order_item_id
    p_user_id,
    p_reference_number,
    p_notes,
    p_cost_per_unit,
    p_location
  );

  -- Get updated quantity
  SELECT quantity INTO v_new_quantity
  FROM inventory
  WHERE variant_id = p_variant_id AND location = p_location;

  -- Return success result
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Inventory restocked successfully',
    'data', jsonb_build_object(
      'variant_id', p_variant_id,
      'location', p_location,
      'quantity_added', p_quantity,
      'previous_quantity', v_current_quantity,
      'new_quantity', v_new_quantity,
      'movement_id', v_movement_id
    )
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Failed to restock inventory: ' || SQLERRM
    );
END;
$function$;
--> statement-breakpoint
